package org.apache.commons.jxpath.ri.compiler;

import java.util.Collection;
import java.util.HashSet;
import java.util.Iterator;

import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;

/**
 * Base implementation of Expression for the operations "&gt;", "&gt;=", "&lt;", "&lt;=".
 * @since JXPath 1.3
 *
 * @author Matt Benson
 * @version $Revision$ $Date$
 */
public abstract class CoreOperationRelationalExpression extends CoreOperation {

    protected CoreOperationRelationalExpression(Expression[] operands) {
        super(operands);
    }

    public final Object computeValue(EvalContext context) {
        final boolean outcome = compute(args[0].computeValue(context),
                args[1].computeValue(context));
        return outcome ? Boolean.TRUE : Boolean.FALSE;
    }

    protected final int getPrecedence() {
        return 3;
    }

    protected final boolean isSymmetric() {
        return false;
    }

    protected abstract boolean evaluateCompare(int compare);

    private boolean compute(Object first, Object second) {
        Object lhs = reduce(first);
        Object rhs = reduce(second);

        if (lhs instanceof InitialContext) {
            ((InitialContext) lhs).reset();
        }
        if (rhs instanceof InitialContext) {
            ((InitialContext) rhs).reset();
        }
        if (lhs instanceof Iterator && rhs instanceof Iterator) {
            return findMatch((Iterator) lhs, (Iterator) rhs);
        }
        if (lhs instanceof Iterator) {
            return containsMatch((Iterator) lhs, rhs);
        }
        if (rhs instanceof Iterator) {
            return containsMatch((Iterator) rhs, lhs);
        }
        final double l = InfoSetUtil.doubleValue(lhs);
        if (Double.isNaN(l)) {
            return false;
        }
        final double r = InfoSetUtil.doubleValue(rhs);
        if (Double.isNaN(r)) {
            return false;
        }
        final int cmp;
        if (l == r) {
            cmp = 0;
        } else if (l < r) {
            cmp = -1;
        } else {
            cmp = 1;
        }
        return evaluateCompare(cmp);
    }

    private Object reduce(Object obj) {
        Object result = obj;
        if (result instanceof SelfContext) {
            result = ((EvalContext) result).getSingleNodePointer();
        }
        if (result instanceof Collection) {
            result = ((Collection) result).iterator();
        }
        return result;
    }

    private boolean containsMatch(Iterator iter, Object value) {
        boolean matched = false;
        while (!matched && iter.hasNext()) {
            Object element = iter.next();
            matched = compute(element, value);
        }
        return matched;
    }

    private boolean findMatch(Iterator leftIter, Iterator rightIter) {
        final HashSet leftSet = new HashSet();
        while (leftIter.hasNext()) {
            leftSet.add(leftIter.next());
        }
        boolean found = false;
        while (!found && rightIter.hasNext()) {
            found = containsMatch(leftSet.iterator(), rightIter.next());
        }
        return found;
    }

}
